"""Random frame sequences, including runs that stay clean and runs with one
corrupted frame in the middle that must not disturb the frames after it."""


def _checksum(data, counter):
    check = counter & 0xFF
    for b in data:
        check ^= b
    return check & 0xFF


def generate(rng, count):
    builders = (_clean_run, _one_bad_frame, _skipped_counter)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _frame_line(data, counter, checksum):
    return "%d\n%s\n%d %X" % (
        len(data), " ".join("%02X" % b for b in data), counter, checksum)


def _case(name, lines, description=""):
    return {"name": name, "stdin": "\n".join(lines) + "\n",
            "description": description}


def _clean_run(rng, index):
    start = rng.randrange(16)
    n = rng.randint(3, 6)
    data = [rng.randrange(256) for _ in range(rng.randint(1, 4))]
    lines = []
    for i in range(n):
        counter = (start + i) % 16
        lines.append(_frame_line(data, counter, _checksum(data, counter)))
    return _case("a clean run starting at counter %d #%d" % (start, index),
                 lines)


def _one_bad_frame(rng, index):
    data = [rng.randrange(256) for _ in range(rng.randint(1, 4))]
    lines = [
        _frame_line(data, 0, _checksum(data, 0)),
        _frame_line(data, 1, _checksum(data, 1)),
        # corrupted: checksum does not match counter 2 at all
        _frame_line(data, 2, _checksum(data, 2) ^ 0xFF),
        _frame_line(data, 2, _checksum(data, 2)),
    ]
    return _case("a corrupted frame that must not move the baseline #%d" %
                index, lines,
                "Frame 3 has a deliberately wrong checksum; frame 4 repeats "
                "counter 2 and must still be accepted, counted from frame "
                "2's counter of 1.")


def _skipped_counter(rng, index):
    data = [rng.randrange(256) for _ in range(rng.randint(1, 4))]
    lines = [
        _frame_line(data, 0, _checksum(data, 0)),
        _frame_line(data, 2, _checksum(data, 2)),  # valid checksum, wrong counter
    ]
    return _case("a valid checksum but a skipped counter #%d" % index, lines,
                 "The checksum is correct for counter 2, but the sequence "
                 "jumped from 0 straight to 2.")
